 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Join diagonally aligned 1 markers, leaving any other marker intact.
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr != 0 and abs(dr) == abs(dc):
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                for k in range(1, abs(dr)):
                    r, c = r1 + sr * k, c1 + sc * k
                    if grid[r][c] == 4 or grid[r][c] == 1:
                        out[r][c] = 1

    # Extend each 6 marker along its diagonal to both grid edges.
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    for r0, c0 in sixes:
        for sr, sc in ((1, 1), (1, -1)):
            # Each cell on the marker's diagonal is visited from the marker.
            for sign in (-1, 1):
                r, c = r0, c0
                while 0 <= r < h and 0 <= c < w:
                    if grid[r][c] in (4, 6):
                        out[r][c] = 6
                    r += sign * sr
                    c += sign * sc
    return out
